import { test, expect } from '@playwright/test';

test.describe('Bulk Delete Items', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/items');
  });

  test('should select multiple items and delete them', async ({ page }) => {
    await page.getByRole('checkbox', { name: 'Select Item 1' }).check();
    await page.getByRole('checkbox', { name: 'Select Item 2' }).check();
    await page.getByRole('button', { name: 'Delete Selected' }).click();

    const confirmationDialog = page.getByText('Are you sure you want to delete the selected items?');
    await expect(confirmationDialog).toBeVisible();
    await page.getByRole('button', { name: 'Confirm' }).click();

    await expect(page.getByText('Item 1')).not.toBeVisible();
    await expect(page.getByText('Item 2')).not.toBeVisible();
  });

  test('should not delete items if cancellation is chosen', async ({ page }) => {
    await page.getByRole('checkbox', { name: 'Select Item 3' }).check();
    await page.getByRole('button', { name: 'Delete Selected' }).click();

    const confirmationDialog = page.getByText('Are you sure you want to delete the selected items?');
    await expect(confirmationDialog).toBeVisible();
    await page.getByRole('button', { name: 'Cancel' }).click();

    await expect(page.getByText('Item 3')).toBeVisible();
  });
});
